{
  "references": [
    {
      "id": "R1",
      "summary_ko": "소방 호스에서 위로 뿜어져 나오는 물이 물의 물리 법칙이 아닌 불꽃/화염처럼 보임."
    },
    {
      "id": "R2",
      "summary_ko": "소방관이 영상 내내 전혀 미끄러지지 않음."
    },
    {
      "id": "R3",
      "summary_ko": "소방관이 무릎을 꿇을 때 호스 제어 불가 때문이 아니라 의도적이고 절제된 방식으로 쓰러지는 것처럼 보임."
    },
    {
      "id": "R4",
      "summary_ko": "호스를 통제한 후 소방관이 불이 나지 않은 앞쪽 바닥을 향해 부자연스러운 동작으로 앞으로 넘어지는 것처럼 보임."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "소방관의 오른쪽 허벅지 부위에 작고 둥근 붉은색/주황색 아티팩트가 생성되어 깜빡이다 사라짐."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R1은 소방 호스에서 나오는 물의 부자연스러운 물리적 특성에 관한 것이고, C1은 소방관 허벅지에 나타나는 시각적 아티팩트에 관한 설명이므로 서로 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R2는 소방관이 미끄러지지 않는 동작에 관한 언급이며, C1은 소방관 허벅지에 생성되는 아티팩트에 관한 것이므로 대상과 결함이 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R3는 소방관이 무릎을 꿇는 자세와 동작의 부자연스러움에 관한 것이며, C1은 허벅지 의류 부분의 시각적 아티팩트에 관한 설명입니다."
    },
    {
      "reference_id": "R4",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R4는 소방관이 앞으로 넘어지며 호스를 조준하는 신체 동작에 관한 내용이고, C1은 허벅지에 나타나는 주황색 아티팩트에 관한 내용이므로 서로 다릅니다."
    }
  ]
}
